NAMES = {
    "disable_power_throttling": "Не замедлять фоновые программы (Power Throttling)",
    "mmcss_games": "Приоритет играм при распределении ресурсов",
}

for path in sys.argv[1:]:
    p = Path(path)
    raw = p.read_bytes().decode("utf-8")
    crlf = "\r\n" in raw
    data = json.loads(raw)
    visible = {t["id"] for t in data if not t.get("hidden")}
    assert visible == set(TEXTS), (visible ^ set(TEXTS))
    for t in data:
        if t["id"] in TEXTS:
            t["description"] = TEXTS[t["id"]]
        if t["id"] in NAMES:
            t["name"] = NAMES[t["id"]]
    out = json.dumps(data, ensure_ascii=False, indent=2) + "\n"
    if crlf:
        out = out.replace("\n", "\r\n")
    p.write_bytes(out.encode("utf-8"))
    print("updated", p)
